  "inlineSchema": "// spiderman\n// Modelo de dados do greencode (API). Replica o modelo de dominio do CLI:\n// Organizacao 1-0..1 Contrato, Organizacao 1-N Lote, Lote 1-N Equipamento,\n// Equipamento 1-N Movimentacao. A URL do banco NAO fica aqui (Prisma 7):\n// ela e lida por prisma.config.ts (migracoes) e por src/server/db/prisma.ts (runtime).\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/server/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Papel {\n  admin\n  cadastro\n  almoxarifado\n  auditor\n}\n\nenum StatusLote {\n  recebido\n  em_triagem\n  triagem_completa\n  encerrado\n}\n\nenum StatusEquipamento {\n  aguardando_triagem\n  em_triagem\n  triado\n  desmonte\n  reciclagem\n  descarte_seguro\n  revenda\n}\n\nenum EstadoFisico {\n  novo\n  seminovo\n  bom\n  regular\n  ruim\n  sucata\n}\n\n// Contas de acesso. `versao` implementa o versionamento otimista (ver README).\nmodel Usuario {\n  id           String   @id @default(uuid()) @db.Uuid\n  username     String   @unique\n  senhaHash    String\n  papel        Papel\n  ativo        Boolean  @default(true)\n  versao       Int      @default(1)\n  criadoEm     DateTime @default(now()) @db.Timestamptz(3)\n  atualizadoEm DateTime @default(now()) @updatedAt @db.Timestamptz(3)\n\n  lotes         Lote[]\n  movimentacoes Movimentacao[]\n  auditorias    Auditoria[]\n}\n\nmodel Organizacao {\n  id           String    @id @default(uuid()) @db.Uuid\n  cnpj         String    @unique\n  razaoSocial  String\n  contato      String?\n  // Soft delete: organizacao inativa some das listagens e nao recebe novos lotes/contratos.\n  ativo        Boolean   @default(true)\n  inativadoEm  DateTime? @db.Timestamptz(3)\n  versao       Int       @default(1)\n  criadoEm     DateTime  @default(now()) @db.Timestamptz(3)\n  atualizadoEm DateTime  @default(now()) @updatedAt @db.Timestamptz(3)\n\n  contrato Contrato?\n  lotes    Lote[]\n}\n\n// Um contrato por organizacao (relacao 1-0..1 garantida pelo @unique em organizacaoId).\nmodel Contrato {\n  id                   String   @id @default(uuid()) @db.Uuid\n  organizacaoId        String   @unique @db.Uuid\n  dataInicio           DateTime @db.Date\n  frequenciaColetaDias Int\n  condicoes            String?\n  clausulas            Json?\n  ativo                Boolean  @default(true)\n  versao               Int      @default(1)\n  criadoEm             DateTime @default(now()) @db.Timestamptz(3)\n  atualizadoEm         DateTime @default(now()) @updatedAt @db.Timestamptz(3)\n\n  // Delete definitivo da organizacao remove o contrato em cadeia.\n  organizacao Organizacao @relation(fields: [organizacaoId], references: [id], onDelete: Cascade)\n}\n\nmodel Lote {\n  id             String     @id @default(uuid()) @db.Uuid\n  organizacaoId  String     @db.Uuid\n  nf             String\n  transportadora String\n  dataEntrada    DateTime   @db.Date\n  status         StatusLote @default(recebido)\n  criadoPorId    String     @db.Uuid\n  // Soft delete (em cadeia com a organizacao). O status do lote e DERIVADO dos equipamentos.\n  ativo          Boolean    @default(true)\n  inativadoEm    DateTime?  @db.Timestamptz(3)\n  versao         Int        @default(1)\n  criadoEm       DateTime   @default(now()) @db.Timestamptz(3)\n  atualizadoEm   DateTime   @default(now()) @updatedAt @db.Timestamptz(3)\n\n  organizacao  Organizacao   @relation(fields: [organizacaoId], references: [id], onDelete: Cascade)\n  criadoPor    Usuario       @relation(fields: [criadoPorId], references: [id], onDelete: Restrict)\n  equipamentos Equipamento[]\n\n  @@unique([organizacaoId, nf])\n  @@index([organizacaoId])\n  @@index([status])\n}\n\nmodel Equipamento {\n  id                  String            @id @default(uuid()) @db.Uuid\n  loteId              String            @db.Uuid\n  // O codigo de barras e o proprio id (garantido por CHECK no banco); a coluna existe para a restricao de unicidade explicita.\n  codigoBarrasInterno String            @unique\n  // Posicao automatica dentro do lote (1, 2, 3...), como o indice de um array.\n  posicao             Int\n  tipo                String\n  estadoFisico        EstadoFisico      @default(novo)\n  status              StatusEquipamento @default(aguardando_triagem)\n  triagemCompleta     Boolean           @default(false)\n  versao              Int               @default(1)\n  criadoEm            DateTime          @default(now()) @db.Timestamptz(3)\n  atualizadoEm        DateTime          @default(now()) @updatedAt @db.Timestamptz(3)\n\n  lote          Lote           @relation(fields: [loteId], references: [id], onDelete: Cascade)\n  movimentacoes Movimentacao[]\n\n  @@unique([loteId, posicao])\n  @@index([loteId])\n  @@index([status])\n}\n\n// Historico imutavel de mudancas de status/estado fisico (rastreabilidade).\nmodel Movimentacao {\n  id            String             @id @default(uuid()) @db.Uuid\n  equipamentoId String             @db.Uuid\n  usuarioId     String             @db.Uuid\n  statusDe      StatusEquipamento?\n  statusPara    StatusEquipamento?\n  estadoDe      EstadoFisico?\n  estadoPara    EstadoFisico?\n  justificativa String?\n  criadoEm      DateTime           @default(now()) @db.Timestamptz(3)\n\n  equipamento Equipamento @relation(fields: [equipamentoId], references: [id], onDelete: Cascade)\n  usuario     Usuario     @relation(fields: [usuarioId], references: [id], onDelete: Restrict)\n\n  @@index([equipamentoId, criadoEm])\n}\n\n// Equivalente ao journal do CLI: trilha de auditoria gravada na MESMA\n// transacao da operacao (ou ambos persistem, ou nenhum).\nmodel Auditoria {\n  id        BigInt   @id @default(autoincrement())\n  usuarioId String?  @db.Uuid\n  acao      String\n  detalhes  Json?\n  criadoEm  DateTime @default(now()) @db.Timestamptz(3)\n\n  usuario Usuario? @relation(fields: [usuarioId], references: [id], onDelete: SetNull)\n\n  @@index([criadoEm])\n  @@index([acao])\n}\n\n// Parametros globais do sistema (equivalente ao arquivo parametros.dat do CLI): pares chave/valor geridos pelo admin.\nmodel ParametroGlobal {\n  chave        String   @id\n  valor        String\n  versao       Int      @default(1)\n  atualizadoEm DateTime @default(now()) @updatedAt @db.Timestamptz(3)\n}\n",
